CREATE     PROCEDURE [synapse_fo].[usp_Insert_ECORESPRODUCT]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:29:46
	Description: Insert stored procedure for ECORESPRODUCT from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[ECORESPRODUCT]
	(
		[DataLakeModified_DateTime],
		[DISPLAYPRODUCTNUMBER],
		[ENGCHGPRODUCTCATEGORYDETAILS],
		[ENGCHGPRODUCTOWNERID],
		[ENGCHGPRODUCTREADINESSPOLICY],
		[ENGCHGPRODUCTRELEASEPOLICY],
		--[FileName],
		[INSTANCERELATIONTYPE],
		--[ISPRODUCTVARIANTUNITCONVERSIONENABLED],
		[LastProcessedChange_DateTime],
		--[LSN],
		[MODIFIEDBY],
		[PARTITION],
		[PDSCWPRODUCT],
		--[PRODUCTMASTER],
		[PRODUCTTYPE],
		[RECID],
		[RECVERSION],
		--[RELATIONTYPE],
		--[RETAILCOLORGROUPID],
		--[RETAILSIZEGROUPID],
		--[RETAILSTYLEGROUPID],
		--[RETAITOTALWEIGHT],
		--[RICSPRODPRICECALC],
		[SEARCHNAME],
		[SERVICETYPE]
		--[SysRowId],
		--[VARIANTCONFIGURATIONTECHNOLOGY]
	)
	SELECT 
		stg.[DataLakeModified_DateTime],
		stg.[DISPLAYPRODUCTNUMBER],
		stg.[ENGCHGPRODUCTCATEGORYDETAILS],
		stg.[ENGCHGPRODUCTOWNERID],
		stg.[ENGCHGPRODUCTREADINESSPOLICY],
		stg.[ENGCHGPRODUCTRELEASEPOLICY],
		--stg.--[FileName],
		stg.[INSTANCERELATIONTYPE],
		--stg.[ISPRODUCTVARIANTUNITCONVERSIONENABLED],
		stg.[LastProcessedChange_DateTime],
		--stg.--[LSN],
		stg.[MODIFIEDBY],
		stg.[PARTITION],
		stg.[PDSCWPRODUCT],
		--stg.[PRODUCTMASTER],
		stg.[PRODUCTTYPE],
		stg.[RECID],
		stg.[RECVERSION],
		--stg.[RELATIONTYPE],
		--stg.[RETAILCOLORGROUPID],
		--stg.[RETAILSIZEGROUPID],
		--stg.[RETAILSTYLEGROUPID],
		--stg.[RETAITOTALWEIGHT],
		--stg.[RICSPRODPRICECALC],
		stg.[SEARCHNAME],
		stg.[SERVICETYPE]
		--stg.--[SysRowId],
		--stg.[VARIANTCONFIGURATIONTECHNOLOGY]	
	FROM [staging_fo].[ECORESPRODUCT] stg
		LEFT JOIN [synapse_fo].[ECORESPRODUCT] tgt
			ON stg.[RECID] = tgt.[RECID] 
		
	WHERE tgt.[RECID] IS NULL
END
